/**
 * Calculates the color of a menu button icon based on the provided parameters.
 *
 * This function returns the color of a menu button icon.
 * If the format block is not empty, it appends the format block to the button name.
 * It then checks if the updated button name exists in the `buttonNameToStyleMapping` object.
 * If it does not exist or is empty, it returns the color `'#FFFFFF'`.
 * If it exists, it retrieves the style name and expected style from the `buttonNameToStyleMapping` object.
 * Finally, it compares the style list with the expected style and returns the color `'#42e1a7'` if they match,
 * or `'#FFFFFF'` if they do not.
 *
 * @see {@link /docs/builder-api/js-beta/divi-module/constants/buttonNameToStyleMapping buttonNameToStyleMapping}
 *
 * @since ??
 *
 * @example
 * ```ts
 * const color = menuButtonIconColor({
 *   buttonName: 'main-menu-text-bold',
 *   formatBlock: 'blockquote',
 *   styleList: {
 *     'bold':      true,
 *     'italic':    true,
 *     'underline': false
 *   }
 * });
 *```
 */
declare const menuButtonIconColor: ({ buttonName, formatBlock, styleList, }: {
    buttonName: string;
    formatBlock?: string;
    styleList: {
        [key: string]: string | false;
    };
}) => string;
export { menuButtonIconColor, };
